<style lang="scss" scoped src="./d-color-radio.scss"></style>

<script>
export default {
  model: {
    prop: "modelValue",
    event: "change",
  },
  props: {
    label: { type: String, default: "", required: true },
    modelValue: { default: "" },
    value: { type: String, default: undefined },
  },
  computed: {
    isChecked() {
      return this.modelValue == this.value;
    },
  },
};
</script>

<template>
  <span class="DColorRadio">
    <input
      class="DColorRadio__radio"
      type="radio"
      :checked="isChecked"
      :value="value"
      @change="$emit('change', $event.target.value)"
      :aria-label="label"
    />
    <span class="DColorRadio__checkmark-border">
      <span
        class="DColorRadio__checkmark-fill"
        :style="{ backgroundColor: value }"
      ></span>
    </span>
  </span>
</template>
